/* ---------- Sync across devices ---------- */
const SYNC_KEY='lifefocus-sync';
let sync=(()=>{try{const v=JSON.parse(localStorage.getItem(SYNC_KEY));return v?.code?v:null;}catch{return null;}})(),syncCrypto=null,syncTimer=null,syncBusy=false,syncAgain=false,syncState='local';
function saveSyncMeta(){try{if(sync)localStorage.setItem(SYNC_KEY,JSON.stringify(sync));else localStorage.removeItem(SYNC_KEY);}catch{}}
async function syncKeys(code=sync?.code){if(!syncCrypto||syncCrypto.code!==code)syncCrypto={code,id:await syncId(code),key:await deriveKey(code)};return syncCrypto;}
function setSyncStatus(s){syncState=s;const el=$('#sync-status');if(el)el.textContent={local:'Saved on this device',syncing:'Syncing…',synced:'Synced across devices',offline:'Offline · will sync later',error:'Sync paused · check settings'}[s];document.body.dataset.sync=s;}
async function api(method,id,body){const r=await fetch(`/api/sync?id=${id}`,{method,headers:body?{'content-type':'application/json'}:{},body:body&&JSON.stringify(body),cache:'no-store'});const data=await r.json().catch(()=>({}));return {status:r.status,data};}
