document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f);if(f.id==='totals-form'){const d=String(data.get('date'));if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||d>localDate(today)){toast('Choose a valid date that isn’t in the future.');return;}const num=k=>{const v=String(data.get(k)??'').trim();return v===''?undefined:Math.round(Number(v)*10)/10;},t={calories:num('calories'),protein:num('protein'),carbs:num('carbs'),fat:num('fat'),fiber:num('fiber')};Object.keys(t).forEach(k=>t[k]===undefined&&delete t[k]);if(!Number.isFinite(t.calories)){toast('Enter your calories for the day.');return;}state.daily[d]={...dayLog(d),totals:t};save();$('#dialog').close();render();const st=calStatus(d);toast(st?`Totals saved · ${statusLabel[st].replace('✓ ','')}`:'Totals saved');return;}if(f.id==='protein-form'){adjustDaily(f.dataset.date,'protein',Number(data.get('grams'))||0);$('#dialog').close();render();toast('Protein added');return;}if(f.id==='reflection-form'){const ws=f.dataset.week,mood=Number(data.get('mood'))||null,wins=String(data.get('wins')||'').trim(),adjust=String(data.get('adjust')||'').trim();if(!mood&&!wins&&!adjust)delete state.reflections[ws];else state.reflections[ws]={mood,wins,adjust,saved:localDate(new Date())};save();render();toast('Weekly check-in saved');return;}if(f.id==='sync-join-form'){joinSync(String(data.get('code')));return;}if(f.id==='injection-form'){const date=String(data.get('date')),dose=Number(data.get('dose'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>localDate(today)){toast('Choose a valid date that isn’t in the future.');return;}if(!(dose>0)){toast('Enter a dose greater than 0 mg.');return;}const entry={id:f.dataset.id||Date.now().toString(36)+Math.random().toString(36).slice(2,6),date,time:String(data.get('time')||''),med:String(data.get('med')||'').trim(),dose,site:String(data.get('site')),effects:data.getAll('effects').map(String),notes:String(data.get('notes')||'').trim()};state.injections=state.injections.filter(x=>x.id!==entry.id);state.injections.push(entry);if(entry.med)state.glp.med=entry.med;save();$('#dialog').close();render();const n=glpStatus();toast(f.dataset.id?'Injection updated':`Injection saved. Next dose ${n.days<=0?'is due now':'due '+dateLabel(n.due,{weekday:'short',month:'short',day:'numeric'})}.`);return;}if(f.id==='glp-settings-form'){state.glp.interval=Math.max(1,Math.round(Number(data.get('interval'))||7));save();$('#dialog').close();render();toast('Injection schedule saved');return;}if(f.id==='swap-session-form'){const other=String(data.get('date'));if(!/^\d{4}-\d{2}-\d{2}$/.test(other)||!Number.isFinite(new Date(other+'T12:00:00').getTime())){toast('Choose a valid date.');return;}if(other===day){toast('Choose a different date to swap with.');return;}undoSessionSwap={...state.sessionDates};state.sessionDates=swapSessions(state.sessionDates,day,other);save();$('#dialog').close();render();toast('Both sessions swapped, including warm-up and cool-down.');return;}if(f.id==='new-exercise-form'){const name=String(data.get('name')).trim();if(!name||name.includes('|')||Object.prototype.hasOwnProperty.call(Object.prototype,name)){toast('Enter an exercise name without the | character or reserved object names.');return;}if(Object.keys(exerciseLibrary).some(n=>n.toLowerCase()===name.toLowerCase())){toast('This exercise already exists. Select it from the exercise dropdown.');return;}const p=Object.fromEntries(['weight','sets','minReps','maxReps'].map(k=>[k,Number(data.get(k))]));if(p.minReps>p.maxReps){toast('Target reps must be at least the minimum reps.');return;}state.customExercises.push(name);state.exerciseDefaults[name]=p;exerciseLibrary[name]=p;state.swaps[sourceDate(state.sessionDates,day)+'|'+f.dataset.slot]=name;save();$('#dialog').close();render();toast('New exercise added and selected');return;}if(f.id==='prescription-form'){const p=Object.fromEntries(['weight','sets','minReps','maxReps'].map(k=>[k,Number(data.get(k))]));if(p.minReps>p.maxReps){toast('Target reps must be at least the minimum reps.');return;}state.exerciseDefaults[f.dataset.name]=p;save();$('#dialog').close();render();return;}if(f.dataset.exercise){const setReps=Array.from({length:dayExercises(day).find(x=>x.name===f.dataset.exercise).sets},(_,i)=>Number(data.get('set'+i)));state.logs[day+'|'+f.dataset.exercise]={weight:Number(data.get('weight')),reps:setReps.at(-1),setReps,effort:data.get('effort')};save();toast('Session saved. Future suggestions updated.');render();}if(f.id==='body-form'){const date=data.get('date');state.body=state.body.filter(x=>x.date!==date);state.body.push({date,weight:Number(data.get('weight'))});save();$('#dialog').close();render();toast('Your check-in is saved');}if(f.id==='meal-form'){const updated=[0,1,2,3,4].map(i=>data.get('meal'+i));updated.forEach((code,i)=>{if(code!==meals(day)[i])delete state.eaten[day+'|'+i];});state.plans[day]=updated;save();$('#dialog').close();render();toast('Meals and grocery list updated');}if(f.id==='settings-form'){const calMin=Number(data.get('calMin'))||null,calMax=Number(data.get('calMax'))||null;if(calMin&&calMax&&calMin>calMax){toast('The calorie minimum must be lower than the maximum.');return;}const unit=data.get('unit');if(unit!==state.unit){const factor=unit==='kg'?1/2.2046226218:2.2046226218;Object.values(state.logs).forEach(l=>l.weight=Math.round(l.weight*factor*100)/100);state.body.forEach(l=>l.weight=Math.round(l.weight*factor*10)/10);Object.values(state.exerciseDefaults).forEach(p=>p.weight=Math.round(p.weight*factor*100)/100);}state.unit=unit;state.step=Number(data.get('step'));state.theme=String(data.get('theme'));state.goals={protein:Number(data.get('protein'))||120,water:Number(data.get('water'))||8,workouts:Number(data.get('workouts'))||3,calMin,calMax};applyTheme();save();$('#dialog').close();render();toast('Preferences saved');}});
